begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();o uuid:=gen_random_uuid();sa uuid;sb uuid;so uuid;sc uuid;guest uuid;p uuid:=gen_random_uuid();r jsonb;rv uuid;other uuid;addr uuid;asset uuid;copy text;f jsonb;receipt jsonb;eid uuid;req uuid:=gen_random_uuid();failed boolean;doc uuid;pr uuid;before_count int;
begin
 insert into auth.users(id,email_confirmed_at) values(a,now()),(b,now()),(o,now());
 insert into memocious_private.admin_users(user_id,role) values(o,'owner');
 sa:=public.memocious_session_open(repeat('7',64),repeat('8',64),a,'customer','fixture','1');
 sb:=public.memocious_session_open(repeat('9',64),repeat('a',64),b,'customer','fixture','1');
 so:=public.memocious_session_open(repeat('b',64),repeat('c',64),o,'admin','fixture','1');
 sc:=public.memocious_session_open(repeat('d',64),repeat('e',64),o,'customer','fixture','1');
 guest:=public.memocious_session_open(repeat('f',64),repeat('0',64),null,'guest',null,'1');
 perform public.memocious_session_mfa(so,repeat('2',64),repeat('3',64),'fixture');
 insert into memocious.products(id,slug,name,active,publication_state,enterprise,moq,lead_days,price_paise) values(p,'phase2-fixture','Phase 2 fixture',true,'published',true,10,3,10000);
 insert into memocious.product_categories(product_id,category_id) select p,id from memocious.categories where slug='corporate-bulk-items';
 insert into memocious.product_images(product_id,public_path,alt,sanitized_at,published_at) values(p,'/media/phase2.webp','Fixture',now(),now());
 perform memocious_private.refresh_publication();
 execute 'set local role service_role';
 r:=public.memocious_review(sa,p,0,'save',0,'<script>inert review</script>','Test');rv:=(r->>'id')::uuid;
 failed:=false;begin perform public.memocious_review(sa,p,0,'save',5,'duplicate','Test');exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Duplicate accepted';end if;
 failed:=false;begin perform public.memocious_review(guest,p,0,'save',5,'guest','Test');exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Guest review accepted';end if;
 perform public.memocious_admin_reviews(so,rv,1,'approve');
 if (select avg_rating from public.memocious_catalogue_products where id=p)<>0 or (select review_count from public.memocious_catalogue_products where id=p)<>1 then raise exception 'Zero aggregate broken';end if;
 if public.memocious_reviews('phase2-fixture')->'items'->0 ?| array['id','user_id','moderated_by','email'] then raise exception 'Private review fields leaked';end if;
 perform public.memocious_review(sb,p,0,'save',4,'Other review','Other');
 other:=(public.memocious_my_reviews(sb)->0->>'id')::uuid;
 perform public.memocious_admin_reviews(so,other,1,'approve');
 if (select avg_rating from public.memocious_catalogue_products where id=p)<>2 then raise exception 'Mixed average broken';end if;
 perform public.memocious_review(sa,p,2,'save',0,'Edited','Test');
 if (select review_count from public.memocious_catalogue_products where id=p)<>1 then raise exception 'Edit retained approval';end if;
 failed:=false;begin perform public.memocious_admin_reviews(so,rv,2,'approve');exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Stale moderation accepted';end if;
 perform public.memocious_review(sa,p,3,'delete');perform public.memocious_review(sa,p,4,'save',0,'Restored','Test');
 if (select count(*) from memocious.reviews where user_id=a and product_id=p)<>1 then raise exception 'Restore duplicated row';end if;
 perform public.memocious_review(sc,p,0,'save',5,'Owner review','Owner');
 failed:=false;begin perform public.memocious_admin_reviews(so,(public.memocious_my_reviews(sc)->0->>'id')::uuid,1,'approve');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Self approval accepted';end if;
 perform public.memocious_review_report(sa,(select public_key from memocious.reviews where id=other),'Test report');
 perform public.memocious_review_report(sa,(select public_key from memocious.reviews where id=other),'Repeated report');
 if (select count(*) from memocious.review_reports where review_id=other)<>1 then raise exception 'Report duplicate';end if;
 if exists(select 1 from jsonb_array_elements(public.memocious_my_reviews(sb)) x where x->>'id'=rv::text) then raise exception 'Other private review leaked';end if;
 -- Owned address edits and cross-user object rejection.
 r:=public.memocious_addresses(sa,'save',null,null,'{"label":"Home","fullName":"Test","lines":"Synthetic address","city":"Test city","state":"Test state","pincode":"400001","phone":"447700900123"}');addr:=(r->0->>'id')::uuid;
 failed:=false;begin perform public.memocious_addresses(sb,'delete',addr,1);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Other address deleted';end if;
 if public.memocious_addresses(sb)<>'[]' then raise exception 'Other address leaked';end if;
 if public.memocious_privacy(sa,'delete-request')->>'status'<>'pending' then raise exception 'Privacy request missing';end if;
 if jsonb_array_length(public.memocious_privacy(sb,'export')->'addresses')<>0 then raise exception 'Export leaked address';end if;
 -- Upload ticket ownership, stale parent, decode contract and publication/revocation.
 asset:=public.memocious_asset_begin(sa,'review',rv,100,'image/png',true);
 failed:=false;begin perform public.memocious_asset(sb,asset,'claim');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Other upload claimed';end if;
 perform public.memocious_asset(sa,asset,'claim');
 failed:=false;begin perform public.memocious_asset(sa,asset,'claim');exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Ticket reused';end if;
 perform public.memocious_asset(sa,asset,'ready',jsonb_build_object('width',100,'height',100,'bytes',100,'digest',repeat('a',64)));
 failed:=false;begin perform public.memocious_asset(null,asset,'public');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Private photo public';end if;
 failed:=false;begin perform public.memocious_admin_reviews(so,rv,6,'approve');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Unprepared photo approved';end if;
 perform public.memocious_asset(so,asset,'publish');perform public.memocious_asset(so,asset,'published');perform public.memocious_admin_reviews(so,rv,6,'approve');
 if public.memocious_asset(null,asset,'public')->>'path' is null then raise exception 'Approved copy missing';end if;
 perform public.memocious_review(sa,p,7,'save',0,'Changed after photo approval','Test');
 failed:=false;begin perform public.memocious_asset(null,asset,'public');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Edited photo still public';end if;
 -- Idempotent guest enterprise and contact, consent, snapshots and pipeline.
 execute 'reset role';update memocious.site_settings set value='true' where key='policies_approved';execute 'set local role service_role';
 f:=jsonb_build_object('contactName','Synthetic','email','fixture@example.invalid','notes','Synthetic fixture','consent',true,'organization','Test','organizationType','company','role','Test','phone','447700900123','gstin','','items',jsonb_build_array(jsonb_build_object('product',p,'quantity',10)),'branding',jsonb_build_object('colours','cream','text','Test'),'deadline',current_date+10,'city','Test','pincode','400001','budgetMinPaise',0,'budgetMaxPaise',1000000);
 receipt:=public.memocious_inquiry(guest,req,'enterprise',f);eid:=(receipt->>'id')::uuid;
 if receipt<>public.memocious_inquiry(guest,req,'enterprise',f) or receipt->>'code'!~'^ENT-[0-9]{4}-[0-9]{6,}-[A-F0-9]{12}$' then raise exception 'Enterprise retry/code';end if;
 failed:=false;begin perform public.memocious_inquiry(guest,req,'enterprise',jsonb_set(f,'{notes}','"changed"'));exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Changed replay accepted';end if;
 failed:=false;begin perform public.memocious_inquiry(guest,gen_random_uuid(),'enterprise',jsonb_set(f,'{items,0,quantity}','1'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'MOQ ignored';end if;
 failed:=false;begin perform public.memocious_inquiry(guest,gen_random_uuid(),'enterprise',jsonb_set(f,'{deadline}',to_jsonb((current_date+1)::text)));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Lead time ignored';end if;
 failed:=false;begin perform public.memocious_asset_begin(sb,'enterprise',eid,100,'image/png',false);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Guest logo claimed by customer';end if;
 perform public.memocious_admin_inquiries(so,eid,1,'update','{"pipeline":"contacted","reason":"Contacted","quotePaise":null,"terms":"","agreement":false}');
 perform public.memocious_admin_inquiries(so,eid,2,'update','{"pipeline":"quote_sent","reason":"Quoted","quotePaise":100000,"terms":"Fixture terms","agreement":false}');
 failed:=false;begin perform public.memocious_admin_inquiries(so,eid,3,'update','{"pipeline":"won","reason":"Clicked","quotePaise":100000,"agreement":false}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Click won accepted';end if;
 perform public.memocious_admin_inquiries(so,eid,3,'update','{"pipeline":"won","reason":"Real agreement fixture","quotePaise":100000,"terms":"Agreed","agreement":true}');
 perform public.memocious_admin_inquiries(so,eid,4,'convert');perform public.memocious_admin_inquiries(so,eid,4,'convert');
 if (select count(*) from memocious.orders where code=receipt->>'code')<>1 or (select payment_received_paise from memocious.orders where code=receipt->>'code')<>0 then raise exception 'Conversion duplicate/payment';end if;
 if (select count(*) from memocious.phase2_events where entity_id=eid)<>5 or (select count(*) from memocious.phase2_outbox b join memocious.phase2_events e on e.id=b.event_id where e.entity_id=eid)<>5 then raise exception 'Atomic events missing';end if;
 req:=gen_random_uuid();f:='{"contactName":"Test","email":"fixture@example.invalid","notes":"Synthetic message","consent":true}';r:=public.memocious_inquiry(guest,req,'contact',f);if r<>public.memocious_inquiry(guest,req,'contact',f) then raise exception 'Contact duplicate';end if;
 perform public.memocious_admin_proof(so,'counter-save',null,null,'{"label":"Synthetic count","value":0,"evidenceReference":"Fixture evidence","active":true}');
 if public.memocious_phase2_public()->'counters'->0->>'value'<>'0' then raise exception 'Zero counter lost';end if;
 perform public.memocious_admin_proof(so,'catalogue-create');
 select id into doc from memocious.catalogue_documents order by created_at desc limit 1;
 failed:=false;begin perform public.memocious_catalogue_document(null,doc);exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Draft PDF public';end if;
 perform public.memocious_admin_proof(so,'catalogue-publish',doc,1);if public.memocious_catalogue_document(null,doc) is null then raise exception 'Published PDF missing';end if;
 execute 'reset role';
end $$;
rollback;
select 'PASS: Phase 2 zero/mixed ratings, edit/moderation versions, restore uniqueness, self approval denial, report dedup, address/export isolation, privacy requests, private media ownership/tickets/publication/revocation, ENT/contact replay/MOQ/date, quote history/order conversion/outbox, counter zero and PDF draft/public boundaries' as result;
